/**
 * TableList Component Tests
 *
 * Tests for the tables page list rendering, status display, and QR code functionality.
 * This file tests the table list display, empty states, loading states,
 * error handling, status badges, and statistics display.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { render } from '@/__tests__/utils/test-utils'
import { createMockSupabaseClient } from '@/__tests__/mocks/supabase'
import TablesPage from '../page'
import type { RestaurantTable, TableStatus } from '@/types/database'

// Mock the Supabase client
vi.mock('@/lib/supabase/client', () => ({
  createClient: vi.fn(),
}))

// Mock the QR code generator
vi.mock('@/lib/qrcode/generator', () => ({
  generateQRCodeSVG: vi.fn(),
  generateQRCodePNG: vi.fn(),
  generateQRCodePDF: vi.fn(),
}))

// Import after mocking to get the mocked version
import { createClient } from '@/lib/supabase/client'
import { generateQRCodeSVG } from '@/lib/qrcode/generator'

/**
 * Create a mock restaurant table with optional overrides
 */
function createMockTable(overrides: Partial<RestaurantTable> = {}): RestaurantTable {
  return {
    id: 'table-' + Math.random().toString(36).substring(7),
    organization_id: 'org-test',
    table_number: 'Masa 1',
    qr_uuid: 'qr-' + Math.random().toString(36).substring(7),
    current_status: 'empty',
    last_ping_at: null,
    ...overrides,
  }
}

describe('TableList', () => {
  const mockOrganizationId = 'test-org-id'
  const mockOrganizationSlug = 'test-restaurant'

  beforeEach(() => {
    vi.clearAllMocks()
  })

  afterEach(() => {
    vi.restoreAllMocks()
  })

  describe('Table List Rendering', () => {
    it('renders table list correctly with tables', async () => {
      // Arrange
      const mockTables = [
        createMockTable({
          id: 'table-1',
          table_number: 'Masa 1',
          qr_uuid: 'qr-uuid-1',
          current_status: 'empty',
          organization_id: mockOrganizationId,
        }),
        createMockTable({
          id: 'table-2',
          table_number: 'Masa 2',
          qr_uuid: 'qr-uuid-2',
          current_status: 'occupied',
          organization_id: mockOrganizationId,
        }),
      ]

      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn((table: string) => {
        if (table === 'restaurant_tables') {
          return createMockQueryBuilder({ selectData: mockTables })
        }
        return createMockQueryBuilder({ selectData: [] })
      })

      mockClient.from = fromMock as any

      function createMockQueryBuilder(config: any) {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: config.selectData,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      render(<TablesPage />, {
        authContext: {
          organization: { id: mockOrganizationId, slug: mockOrganizationSlug } as any,
        },
      })

      // Assert
      await waitFor(() => {
        expect(screen.getByText('Masa 1')).toBeInTheDocument()
      })

      expect(screen.getByText('Masa 2')).toBeInTheDocument()
      expect(screen.getByText(/qr-uuid-1/)).toBeInTheDocument()
      expect(screen.getByText(/qr-uuid-2/)).toBeInTheDocument()
    })

